Object.assign(TR.pt, {"Other covers": "Outras capas", "Find online": "Buscar online", "Looking for covers…": "Procurando capas…", "No other covers found online. You can take a photo instead.": "Nenhuma outra capa encontrada online. Você pode tirar uma foto.", "Back covers are rare online: the likely ones are first. Tap a picture to use it.": "Contracapas são raras online: as mais prováveis vêm primeiro. Toque numa imagem para usá-la.", "Tap the cover you want.": "Toque na capa que você quer.", "Add the back cover with 📷 under “Back”.": "Adicione a contracapa com 📷 em “Verso”.", "🖼️ Not the right cover? Tap “Other covers” under the book to choose another edition’s cover, or “Find online” to look for a back cover.": "🖼️ Não é a capa certa? Toque em “Outras capas” abaixo do livro para escolher a de outra edição, ou em “Buscar online” para procurar a contracapa."});
